// V306l · âm giao diện (Kenney "Interface Sounds" 1.0, CC0 — xem docs_claude/giay_phep/KENNEY_INTERFACE_SOUNDS_CC0.txt). Tôn trọng công tắc âm thanh `sound`.
(()=>{try{
 const SRC={"tap":"","tab":"","ok":"","back":"","open":"","err":"","boss":""};
 let ac=null,out=null;const buf={};
 const okSound=()=>{try{return typeof sound==='undefined'||!!sound;}catch{return true;}};
 function A(){if(ac)return ac;const C=window.AudioContext||window.webkitAudioContext;if(!C)return null;try{ac=new C();out=ac.createGain();out.gain.value=.5;out.connect(ac.destination);}catch{ac=null;}return ac;}
 function dec(k){return new Promise(r=>{try{const b=atob(SRC[k]),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);A().decodeAudioData(u.buffer,x=>{buf[k]=x;r(x);},()=>r(null));}catch{r(null);}});}
 async function play(k){if(!okSound()||!A())return;try{if(ac.state==='suspended')ac.resume().catch(()=>{});const b=buf[k]||await dec(k);if(!b)return;const s=ac.createBufferSource();s.buffer=b;s.connect(out);s.start();}catch{}}
 window.UISND306={play};
 const SEL=[['.m63-x,.cm-x,[data-x="close"],#lobby-back,.cm-prev,.cm-next','back'],
  ['#lb68 .cta.c,.m63 .m63-go,.cm-sheet .cm-go,#dock-return','ok'],
  ['#nav74 button,#nav74s .n74s button,#hub40 .hb-filter button,.cm-world button','tab'],
  ['.h1-ic,.hb-it,#lb68 .cta,.cm-node,.h1-chip','tap']];
 document.addEventListener('click',e=>{const t=e.target&&e.target.closest?e.target.closest('button,.cm-node,.hb-it,.h1-ic,.h1-chip,.cta'):null;if(!t||t.disabled||t.closest('#game-field:not(#overlay)')&&!t.closest('#overlay'))return;
  for(const [s,k] of SEL){if(t.matches(s)){play(k);return;}}},true);
 new MutationObserver(()=>{if(document.getElementById('bw306')&&!window.__bw306s){window.__bw306s=1;play('boss');setTimeout(()=>{window.__bw306s=0;},3000);}}).observe(document.body,{childList:true,subtree:true});
}catch(e){}})();
